private volatile Cache cache;
private volatile boolean dirty = true;

public Cache derived() {
    if (!dirty) return cache;                       // fast path, no lock
    synchronized (this) {
        if (dirty) { cache = buildCache(); dirty = false; }   // publish, then clear
        return cache;
    }
}

