private final AtomicReference<Cache> cache = new AtomicReference<>();

public Cache derived() {
    Cache c = cache.get();
    if (c != null) return c;                        // lock-free read
    return cache.updateAndGet(prev -> prev != null ? prev : buildCache());
}

// invalidation: cache.set(null)

private final StampedLock lock = new StampedLock();
private Cache cache = buildCache();                 // published at construction

public Cache derived() {
    long stamp = lock.tryOptimisticRead();
    Cache c = cache;
    if (!lock.validate(stamp)) {                    // a mutation invalidated it
        stamp = lock.writeLock();
        try { c = cache = buildCache(); } finally { lock.unlockWrite(stamp); }
    }
    return c;
}
